import SwiftUI

// The ASCII theme: a monochrome retro terminal / dot-matrix look with Japanese
// travel-zine accents. Pure black, white ink, mono type, outlined panels with
// notched labels, bracketed buttons and character-grid art generated by
// Design/ascii-art.swift (AsciiArtData.swift).

struct AsciiTheme: SynqTheme {
    let id = "ascii"
    let name = "ASCII"
    let summary = "Black terminal, mono type, character art"
    let colorScheme = ColorScheme.dark

    static func hex(_ v: UInt32) -> Color {
        Color(red: Double((v >> 16) & 0xFF) / 255, green: Double((v >> 8) & 0xFF) / 255, blue: Double(v & 0xFF) / 255)
    }

    let colors = SynqColors(
        background: hex(0x000000), panel: hex(0x0B0B0B),
        inkPrimary: hex(0xF2F2F2), inkSecondary: hex(0xA0A0A0), inkTertiary: hex(0x5A5A5A),
        line: hex(0x3A3A3A), lineStrong: hex(0xF2F2F2),
        approved: hex(0x9BE59B), approvedFill: hex(0x0E1F0E), approvedLine: hex(0x2E5E2E),
        pending: hex(0xA0A0A0), danger: hex(0xE58B8B),
        accent: hex(0xF2F2F2), onAccent: hex(0x000000))

    static let mono = "JetBrainsMono-Regular"
    static let monoMedium = "JetBrainsMono-Medium"
    static let monoBold = "JetBrainsMono-Bold"
    static let pixel = "DepartureMono-Regular"
    static let japanese = "NotoSansJP-Regular"

    let type = SynqTypography(roles: [
        .wordmark: SynqFontSpec(family: pixel, size: 40, relativeTo: .largeTitle, tracking: 1, fixed: true),
        .wordmarkSub: SynqFontSpec(family: japanese, size: 12, fallback: .default, relativeTo: .caption, tracking: 2, fixed: true),
        .title: SynqFontSpec(family: pixel, size: 17, relativeTo: .headline, tracking: 2.2, uppercase: true),
        .headline: SynqFontSpec(family: pixel, size: 22, relativeTo: .title2, tracking: 0.5),
        .sectionLabel: SynqFontSpec(family: mono, size: 11.5, relativeTo: .caption, tracking: 1.4, uppercase: true),
        .amountLarge: SynqFontSpec(family: pixel, size: 38, relativeTo: .largeTitle, tracking: 0.5),
        .amountMedium: SynqFontSpec(family: pixel, size: 20, relativeTo: .title3, tracking: 0.3),
        .amountUnit: SynqFontSpec(family: pixel, size: 17, relativeTo: .headline, tracking: 0.5),
        .body: SynqFontSpec(family: mono, size: 14, relativeTo: .body),
        .bodyStrong: SynqFontSpec(family: monoMedium, size: 15, weight: .medium, relativeTo: .body),
        .caption: SynqFontSpec(family: mono, size: 11.5, relativeTo: .caption),
        .mono: SynqFontSpec(family: mono, size: 12, relativeTo: .caption),
        .button: SynqFontSpec(family: monoMedium, size: 14.5, weight: .medium, relativeTo: .body, tracking: 0.3),
        .keypad: SynqFontSpec(family: pixel, size: 22, relativeTo: .title2, fixed: true),
        .tab: SynqFontSpec(family: japanese, size: 10, fallback: .default, relativeTo: .caption2, fixed: true),
        .tagline: SynqFontSpec(family: japanese, size: 15, fallback: .default, relativeTo: .body, fixed: true),
        .display: SynqFontSpec(family: japanese, size: 25, fallback: .default, relativeTo: .title, tracking: 2),
    ], artFamily: mono)

    let space = SynqSpacing()
    let radius = SynqRadii(panel: 7, control: 7, badge: 3, key: 5, bubble: 16)
    let lines = SynqLines(hairline: 1, control: 1, ruleDash: [2, 3])
    let motion = SynqMotion()
    let glyphs = SynqGlyphs(bracketOpen: "[", bracketClose: "]", strongOpen: "{", strongClose: "}",
                            rowArrow: "[→]", cursor: "▌", prompt: ">",
                            spinner: ["|", "/", "-", "\\"])

    let copy = SynqFlavor(
        wordmark: "SYNQ", wordmarkSub: "シンク",
        taglines: [.home: "旅を共に", .fund: "一緒に、\nもっと遠くへ", .send: "小さな支払いが、\n大きな思い出に。",
                   .gift: "贈り物を、\nみんなで", .receipt: "記録は、\nここに", .deal: "話し合って、\n決める",
                   .risk: "安心して、\n進む", .agent: "みんなで\n考える"],
        tabs: [.home: "ホーム", .trips: "旅行", .gifts: "ギフト", .group: "グループ", .ask: "S"],
        centreTab: "S", seeAll: "すべて見る", flightsHeadline: "どこへ行きますか？",
        places: SynqFlavor.airportCoordinates)

    let icons = SynqIcons(symbols: [:], weight: .light)

    let looks = SynqLooks(panelLabel: .notched, panelFilled: false, avatar: .pixel, progress: .outlined,
                          uppercaseTitles: true, ruledSections: true)

    func art(_ slot: SynqArtSlot, _ variant: SynqArtVariant) -> AnyView {
        let piece = AsciiArtwork.piece(slot, variant)
        guard variant == .hero else {
            return AnyView(AsciiArtView(art: piece, ink: colors.inkPrimary, dim: colors.inkSecondary, family: type.artFamily))
        }
        return AnyView(AsciiHeroBand(art: piece, tagline: copy.taglines[slot], placement: Self.placement(slot),
                                     ink: colors.inkPrimary, dim: colors.inkSecondary, artFamily: type.artFamily,
                                     taglineFont: type[.tagline]))
    }

    /// Where the vertical tagline sits beside each hero.
    static func placement(_ slot: SynqArtSlot) -> (alignment: Alignment, top: CGFloat) {
        switch slot {
        case .send: return (.topLeading, 20)
        case .fund: return (.topTrailing, 52)
        default: return (.topTrailing, 8)
        }
    }
}

// MARK: - Character-grid art

struct AsciiArtwork: Equatable {
    let cols: Int
    let rows: [String]

    /// Cell height over width, matching the generator.
    static let cellAspect: CGFloat = 1.8
    var aspect: CGFloat { CGFloat(cols) / (CGFloat(rows.count) * Self.cellAspect) }

    static func piece(_ slot: SynqArtSlot, _ variant: SynqArtVariant) -> AsciiArtwork {
        let hero = variant == .hero
        switch slot {
        case .home: return hero ? home : homeStrip
        case .flights: return hero ? flights : flightsStrip
        case .fund: return hero ? fund : fundStrip
        case .send: return hero ? send : sendStrip
        case .gift: return hero ? gift : giftStrip
        case .receipt: return hero ? receipt : receiptStrip
        case .deal: return hero ? deal : dealStrip
        case .risk: return hero ? risk : riskStrip
        case .agent: return hero ? agent : agentStrip
        }
    }
}

/// Draws a character grid crisply at any width: each glyph is placed in its cell.
struct AsciiArtView: View {
    let art: AsciiArtwork
    let ink: Color
    let dim: Color
    let family: String?

    static let dimGlyphs: Set<Character> = [".", ",", "'", "`", ":", "·"]

    var body: some View {
        Canvas { ctx, size in
            let cw = size.width / CGFloat(art.cols)
            let ch = cw * AsciiArtwork.cellAspect
            let fontSize = cw / 0.6
            let font: Font = family.map { SynqFonts.isAvailable($0) ? Font.custom($0, fixedSize: fontSize) : nil }
                .flatMap { $0 } ?? .system(size: fontSize, design: .monospaced)
            var cache: [Character: GraphicsContext.ResolvedText] = [:]
            for (r, row) in art.rows.enumerated() {
                let y = (CGFloat(r) + 0.5) * ch
                for (c, glyph) in row.enumerated() where glyph != " " {
                    let text: GraphicsContext.ResolvedText
                    if let hit = cache[glyph] {
                        text = hit
                    } else {
                        text = ctx.resolve(Text(String(glyph)).font(font)
                            .foregroundColor(Self.dimGlyphs.contains(glyph) ? dim : ink))
                        cache[glyph] = text
                    }
                    ctx.draw(text, at: CGPoint(x: (CGFloat(c) + 0.5) * cw, y: y), anchor: .center)
                }
            }
        }
        .aspectRatio(art.aspect, contentMode: .fit)
        .accessibilityHidden(true)
    }
}

/// A hero band: full-bleed art with a vertical Japanese tagline beside it.
struct AsciiHeroBand: View {
    let art: AsciiArtwork
    let tagline: String?
    let placement: (alignment: Alignment, top: CGFloat)
    let ink: Color
    let dim: Color
    let artFamily: String?
    let taglineFont: SynqFontSpec

    var body: some View {
        AsciiArtView(art: art, ink: ink, dim: dim, family: artFamily)
            .overlay(alignment: placement.alignment) {
                if let tagline {
                    VerticalText(text: tagline, font: taglineFont.font, size: taglineFont.size, ink: ink)
                        .padding(.top, placement.top)
                        .padding(.horizontal, 14)
                }
            }
            .accessibilityHidden(true)
    }
}

/// Japanese set vertically: columns run top to bottom, right to left.
struct VerticalText: View {
    let text: String
    let font: Font
    let size: CGFloat
    let ink: Color

    /// Vertical presentation forms for punctuation.
    private static func vertical(_ c: Character) -> String {
        switch c {
        case "、": return "︑"
        case "。": return "︒"
        case "ー": return "｜"
        default: return String(c)
        }
    }

    var body: some View {
        HStack(alignment: .top, spacing: 6) {
            ForEach(Array(text.split(separator: "\n").reversed().enumerated()), id: \.offset) { _, column in
                VStack(spacing: 0) {
                    ForEach(Array(column.enumerated()), id: \.offset) { _, c in
                        Text(Self.vertical(c)).font(font).foregroundStyle(ink).frame(height: size * 1.12)
                    }
                }
            }
        }
        .fixedSize()
        .accessibilityHidden(true)
    }
}
